  const phase=reduced?2.4:(seconds%18)/2;
  const q=motion/9, dz=.059*q,tx=18*q,ty=-7*q;
  const scale=Math.min(W/BW,H/BH);
  ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  ctx.globalCompositeOperation='lighter';
  for(const [ox,oy,z,b,r,pi,glint,i] of STARS){
   const depth=z-dz;
   const px=((ox+tx*.30)/depth+BW*.48)/BW*W,py=((oy+ty*.29)/depth+BH*.50)/BH*H;
   const a=r*(z/depth)*scale;
   if(px<-.01*W||px>1.01*W||py<-.015*H||py>1.015*H)continue;
   let bright=b/255,pulse=0;
   if(glint){
    const step=stellarTiming[i], local=entryBreath(phase,step);
    // Carry the tail of recently lit stars into the next lap; introduce
    // new glows independently of a loop reset instead of dropping them.
    const previous=seconds>=18?entryBreath(phase+9,step):0;
    const next=entryBreath(phase-9,step);
    pulse=Math.min(1,Math.max(local,previous,next));
    bright*=step.floor+(1-step.floor)*pulse;
    ctx.globalAlpha=Math.min(1,bright*(.27+.10*pulse));
    drawSprite(glow[pi],px,py,Math.max(.75,a*7.5));
    ctx.globalAlpha=Math.min(1,bright*.18*pulse);
    const rr=Math.max(.7,a*6.0);
    if(rr>.8&&pulse>.05)drawSprite(rays[pi],px,py,rr);
   }else if(z<3.6){
    bright*=1+.045*Math.sin(motion*.83+ox*.012);
    if(warm(PALETTE[pi])){
     ctx.globalAlpha=Math.min(1,bright*.125);
     drawSprite(glow[pi],px,py,Math.max(.55,a*6.1));
    }
   }
   ctx.globalAlpha=Math.min(1,bright);
   drawSprite(glint?near[pi]:normal[pi],px,py,Math.max(.48,a*3.1));
  }
  if(!reduced&&options.meteors!==false)meteors(phase,1);
